package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.service.jobs.GenerationFlowService.Stage;
import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.JsonNode;

class FrozenReferenceClosureTest {
 final ContentVersionKey root=new ContentVersionKey("report","fictional-report",2,"a".repeat(64),"fictional-root"),middle=new ContentVersionKey("report","fictional-middle",4,"b".repeat(64),"fictional-middle-root");
 FrozenApplicationContext context(String id,String targets,boolean complete){return FrozenApplicationContext.fromJson(CanonicalJson.parse(FrozenApplicationContextTest.context(Stage.DAILY_REPORT).replace("fictional-report",id).replace("[{\"kind\":\"article_revision\",\"id\":\"fictional-citation\"}]",targets).replace("\"references_complete\":true","\"references_complete\":"+complete)));}
 String target(ContentVersionKey v){return com.lianxibu.site.repository.jobs.JdbcFrozenInputs.canonical(FrozenReferenceClosure.version(v));}
 final String leaf="{\"kind\":\"article_revision\",\"id\":\"fictional-citation\"}";
 FrozenReferenceClosure.Source source(Map<ContentVersionKey,FrozenApplicationContext> contexts,boolean leafExists){return new FrozenReferenceClosure.Source(){public FrozenReferenceClosure.Evidence resolve(ContentVersionKey v){return contexts.containsKey(v)?new FrozenReferenceClosure.Evidence(v,contexts.get(v)):null;}public boolean leafExists(JsonNode target){return leafExists;}};}
 @Test void exactMiddleAndLeafReferencesAreExpandedDeduplicatedAndDefensivelyReturned(){var first=context(root.contentId(),"["+target(middle)+","+leaf+"]",true);var second=context(middle.contentId(),"["+leaf+"]",true);var result=new FrozenReferenceClosure(source(Map.of(middle,second),true)).expand(root,first);assertEquals(2,result.targets().size());assertTrue(Arrays.compareUnsigned(CanonicalJson.bytes(result.targets().get(0)),CanonicalJson.bytes(result.targets().get(1)))<0);var returned=result.targets().stream().filter(t->t.path("kind").asText().equals("article_revision")).findFirst().orElseThrow();((tools.jackson.databind.node.ObjectNode)returned).put("id","fictional-mutated");assertEquals("fictional-citation",result.targets().stream().filter(t->t.path("kind").asText().equals("article_revision")).findFirst().orElseThrow().path("id").asText());}
 @Test void explicitEmptyClosureWorksButMissingIncompleteAndOtherVersionProofsFail(){var empty=context(root.contentId(),"[]",true);assertTrue(new FrozenReferenceClosure(source(Map.of(),false)).expand(root,empty).targets().isEmpty());var first=context(root.contentId(),"["+target(middle)+"]",true);assertThrows(IllegalStateException.class,()->new FrozenReferenceClosure(source(Map.of(),true)).expand(root,first));assertThrows(IllegalStateException.class,()->new FrozenReferenceClosure(source(Map.of(middle,context(middle.contentId(),"[]",false)),true)).expand(root,first));var wrong=new FrozenReferenceClosure.Source(){public FrozenReferenceClosure.Evidence resolve(ContentVersionKey v){return new FrozenReferenceClosure.Evidence(root,empty);}public boolean leafExists(JsonNode v){return true;}};assertThrows(IllegalStateException.class,()->new FrozenReferenceClosure(wrong).expand(root,first));assertThrows(IllegalStateException.class,()->new FrozenReferenceClosure(source(Map.of(),true)).expand(root,context(root.contentId(),"[]",false)));}
 @Test void exactVersionCycleLeafLossAndBoundedClosureFailClosed(){var first=context(root.contentId(),"["+target(middle)+"]",true);var second=context(middle.contentId(),"["+target(root)+"]",true);assertThrows(IllegalStateException.class,()->new FrozenReferenceClosure(source(Map.of(middle,second),true)).expand(root,first));assertThrows(IllegalStateException.class,()->new FrozenReferenceClosure(source(Map.of(),false)).expand(root,context(root.contentId(),"["+leaf+"]",true)));var valid=context(middle.contentId(),"["+leaf+"]",true);assertThrows(IllegalStateException.class,()->new FrozenReferenceClosure(source(Map.of(middle,valid),true),1).expand(root,first));}
 @Test void sameStableIdAtDifferentHistoricalVersionsDoesNotFormFalseCycle(){var older=new ContentVersionKey(root.contentKind(),root.contentId(),1,"c".repeat(64),"fictional-earlier-root");var first=context(root.contentId(),"["+target(older)+"]",true);var past=context(root.contentId(),"["+leaf+"]",true);assertEquals(2,new FrozenReferenceClosure(source(Map.of(older,past),true)).expand(root,first).targets().size());}
}
